fn real(op: &str, p: usize, a: &[ExactNum], cc: &mut Consts) -> ExactNum {
    let x = &a[0];
    match op {
        "erf" => x.erf(p, RM, cc),
        "erfc" => x.erfc(p, RM, cc),
        "ln_gamma" => x.ln_gamma(p, RM, cc),
        "gamma" => x.gamma(p, RM, cc),
        "normal_cdf" => x.normal_cdf(&a[1], &a[2], p, RM, cc),
        "ai" => x.ai(p, RM, cc),
        "bi" => x.bi(p, RM, cc),
        "ai_prime" => x.ai_prime(p, RM, cc),
        "bi_prime" => x.bi_prime(p, RM, cc),
        "ei" => x.ei(p, RM, cc),
        "ci" => x.ci(p, RM, cc),
        "li" => x.li(p, RM, cc),
        "fresnel_s" => x.fresnel_s(p, RM, cc),
        "fresnel_c" => x.fresnel_c(p, RM, cc),
        "bessel_j" => x.bessel_j_nu(&a[1], p, RM, cc),
        "bessel_y" => x.bessel_y(&a[1], p, RM, cc),
        "bessel_k" => x.bessel_k(&a[1], p, RM, cc),
        "betainc" => x.betainc(&a[1], &a[2], p, RM, cc),
        "log" => x.log(&a[1], p, RM, cc),
        "jacobi_cd" => x.jacobi_cd(&a[1], p, RM, cc),
        "jacobi_dc" => x.jacobi_dc(&a[1], p, RM, cc),
        "elliptic_pi" => x.elliptic_pi(&a[1], &a[2], p, RM, cc),
        "elliptic_pi_complete" => x.elliptic_pi_complete(&a[1], p, RM, cc),
        _ => panic!("unknown op {op}"),
    }
}

fn cplx(op: &str, p: usize, a: &[ExactComplex], cc: &mut Consts) -> ExactComplex {
    let z = &a[0];
    match op {
        "c.ci" => z.ci(p, RM, cc),
        "c.si" => z.si(p, RM, cc),
        "c.acosh" => z.acosh(p, RM, cc),
        "c.ei" => z.ei(p, RM, cc),
        "c.ai" => z.ai(p, RM, cc),
        "c.bi" => z.bi(p, RM, cc),
        "c.bessel_j" => z.bessel_j_nu(&a[1], p, RM, cc),
        "c.bessel_i" => z.bessel_i(&a[1], p, RM, cc),
        "c.bessel_k" => z.bessel_k(&a[1], p, RM, cc),
        "c.hyp2f1" => z.hypergeom_2f1(&a[1], &a[2], &a[3], p, RM, cc),
        "c.ln_gamma" => z.ln_gamma(p, RM, cc),
        "c.gamma" => z.gamma(p, RM, cc),
        "c.erf" => z.erf(p, RM, cc),
        _ => panic!("unknown op {op}"),
    }
}

/// Binary exponent of a nonzero value (`i32::MIN` for zero).
fn mag(x: &ExactNum) -> i32 {
    if x.is_zero() {
        i32::MIN
    } else {
        x.exponent().unwrap_or(i32::MIN)
    }
}

/// Correct bits of `got` against `want`, relative to the magnitude of `scale`
/// (`i32::MAX` if equal, `i32::MIN` if `got` is NaN).
fn bits(got: &ExactNum, want: &ExactNum, scale: &ExactNum, p: usize) -> i32 {
    if got.is_nan() {
        return i32::MIN;
    }
    let d = got.sub(want, 2 * p, RoundingMode::None);
    if d.is_zero() {
        return i32::MAX;
    }
    scale.exponent().unwrap_or(0) - d.exponent().unwrap_or(0)
}

#[test]
fn special_audit_mpmath() {
    let mut cc = Consts::new().unwrap();
    let parse = |s: &str, p: usize, cc: &mut Consts| ExactNum::parse(s, Radix::Dec, p, RM, cc);
    let mut failures = Vec::new();
    for &(op, p, args, re, im) in CASES {
        let want_re = parse(re, 4 * p, &mut cc);
        let (b, got) = if op.starts_with("c.") {
            let zs: Vec<ExactComplex> = args
                .iter()
                .map(|s| {
                    let (a, b) = s.split_once(',').unwrap();
                    ExactComplex::new(parse(a, p, &mut cc), parse(b, p, &mut cc))
                })
                .collect();
            let want_im = parse(im, 4 * p, &mut cc);
            let g = cplx(op, p, &zs, &mut cc);
            let scale = if mag(&want_re) >= mag(&want_im) { &want_re } else { &want_im };
            let b = bits(g.re(), &want_re, scale, p).min(bits(g.im(), &want_im, scale, p));
            (b, format!("{:?}", g.re().err().or(g.im().err())))
        } else {
            let xs: Vec<ExactNum> = args
                .iter()
                .enumerate()
                .map(|(i, s)| {
                    if op == "nth_root" && i == 1 {
                        ExactNum::new(p)
                    } else {
                        parse(s, p, &mut cc)
                    }
                })
                .collect();
            let g = if op == "nth_root" {
                xs[0].nth_root(args[1].parse().unwrap(), p, RM)
            } else {
                real(op, p, &xs, &mut cc)
            };
            (bits(&g, &want_re, &want_re, p), format!("{:?}", g.err()))
        };
        if b < (p as i32) - 2 {
            failures.push(format!("{op} p={p} {args:?}: {b} correct bits {got}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
